 (slug, district, title_en, title_el, title_ro, title_ar, summary_en, summary_el, summary_ro, summary_ar, venue, starts_at, ends_at, price, url, image, lat, lng, tags, status, source_url, organizer, organizer_email, coords_precision, recurrence, date_confidence, notes)
values
('cyprus-wine-festival-limassol', 'limassol', 'Cyprus Wine Festival (Limassol)', 'Cyprus Wine Festival (Limassol)', 'Cyprus Wine Festival (Limassol)', 'Cyprus Wine Festival (Limassol)', 'Cyprus''s largest and oldest wine celebration, the 65th edition runs nine days with tastings from local wineries, folklore dancing, traditional food and live performances. Held each year in the seafront Municipal Gardens.', 'Η μεγαλύτερη και παλαιότερη γιορτή κρασιού της Κύπρου· η 65η διοργάνωση διαρκεί εννέα ημέρες με γευσιγνωσίες από τοπικά οινοποιεία, παραδοσιακούς χορούς, παραδοσιακό φαγητό και ζωντανές εμφανίσεις. Πραγματοποιείται κάθε χρόνο στον παραθαλάσσιο Δημοτικό Κήπο.', 'Cea mai mare și mai veche sărbătoare a vinului din Cipru; ediția a 65-a se desfășoară pe parcursul a nouă zile, cu degustări de la cramele locale, dansuri folclorice, mâncare tradițională și spectacole live. Se organizează în fiecare an în Grădina Municipală de pe faleză.', 'أكبر وأقدم احتفال بالنبيذ في قبرص، وتمتدّ نسخته الخامسة والستون تسعة أيام تتخللها تذوّقات من مصانع النبيذ المحلية ورقصات فولكلورية وأطعمة تقليدية وعروض حية. يُقام سنويًا في الحدائق البلدية على الواجهة البحرية.', 'Limassol Municipal Gardens', '2026-09-26 18:00:00+03'::timestamptz, '2026-10-04 23:00:00+03'::timestamptz, null, 'https://www.limassoltourism.com/events/the-cyprus-wine-festival-2026/', null, 34.6772, 33.0561, array['wine','festival','food','limassol']::text[], 'published', 'https://evoinos.com/limassol-wine-festival/', 'Municipality of Limassol', null, 'exact', 'annual', 'confirmed', 'date_confidence=confirmed; recurrence=annual'),
('42nd-ayia-napa-international-festival', 'famagusta', '42nd Ayia Napa International Festival', '42nd Ayia Napa International Festival', '42nd Ayia Napa International Festival', '42nd Ayia Napa International Festival', 'A free open-air cultural festival featuring local and visiting dance and music groups, concerts with Cypriot and Greek performers, craft demonstrations and food stalls. Centred on Ayia Napa''s main square and monastery.', 'Ένα δωρεάν υπαίθριο πολιτιστικό φεστιβάλ με τοπικά και φιλοξενούμενα χορευτικά και μουσικά συγκροτήματα, συναυλίες με Κύπριους και Έλληνες καλλιτέχνες, επιδείξεις χειροτεχνίας και πάγκους με φαγητό. Με επίκεντρο την κεντρική πλατεία και το μοναστήρι της Αγίας Νάπας.', 'Un festival cultural gratuit în aer liber, cu grupuri de dans și muzică locale și invitate, concerte cu artiști ciprioți și greci, demonstrații de meșteșuguri și standuri cu mâncare. Concentrat în jurul pieței principale și al mănăstirii din Ayia Napa.', 'مهرجان ثقافي مجاني في الهواء الطلق يضمّ فرق رقص وموسيقى محلية وزائرة وحفلات لفنانين قبارصة ويونانيين وعروضًا حرفية وأكشاك طعام. يتمركز حول الساحة الرئيسية والدير في أيا نابا.', 'Ayia Napa Main Square & Monastery', '2026-09-25 19:00:00+03'::timestamptz, '2026-09-27 23:00:00+03'::timestamptz, 'Free', 'https://www.loveayianapa.com/festivals-in-ayia-napa.html', null, 34.9884, 33.9998, array['cultural','music','dance','famagusta']::text[], 'published', 'https://cyprus-mail.com/2026/03/08/ayia-napa-festivals-to-look-forward-to', 'Ayia Napa Municipality', null, 'exact', 'annual', 'confirmed', 'date_confidence=confirmed; recurrence=annual'),
('buffer-fringe-performing-arts-festival', 'nicosia', 'Buffer Fringe Performing Arts Festival', 'Buffer Fringe Performing Arts Festival', 'Buffer Fringe Performing Arts Festival', 'Buffer Fringe Performing Arts Festival', 'Cyprus''s only Fringe festival, staged in and around the UN buffer zone with performances that use the arts to encourage intercommunal dialogue. The 2026 edition features 13 artists and groups across three Nicosia venues.', 'Το μοναδικό φεστιβάλ Fringe της Κύπρου, που ανεβαίνει μέσα και γύρω από τη νεκρή ζώνη του ΟΗΕ, με παραστάσεις που αξιοποιούν τις τέχνες για να ενθαρρύνουν τον διακοινοτικό διάλογο. Η διοργάνωση του 2026 περιλαμβάνει 13 καλλιτέχνες και ομάδες σε τρεις χώρους της Λευκωσίας.', 'Singurul festival Fringe din Cipru, organizat în și în jurul zonei tampon a ONU, cu spectacole care folosesc artele pentru a încuraja dialogul intercomunitar. Ediția din 2026 reunește 13 artiști și grupuri în trei spații din Nicosia.', 'مهرجان Fringe الوحيد في قبرص، يُقام داخل المنطقة العازلة التابعة للأمم المتحدة وحولها بعروض توظّف الفنون لتعزيز الحوار بين الطوائف. تضمّ نسخة 2026 ثلاثة عشر فنانًا ومجموعة في ثلاثة أماكن بنيقوسيا.', 'Home for Cooperation & buffer-zone venues, Nicosia', '2026-10-02 18:00:00+03'::timestamptz, '2026-10-04 23:00:00+03'::timestamptz, 'Free', 'https://bufferfringe.org/', null, 35.1745, 33.3596, array['performing-arts','theatre','cultural','nicosia']::text[], 'published', 'https://bufferfringe.org/', 'Home for Cooperation (H4C)', null, 'exact', 'annual', 'confirmed', 'date_confidence=confirmed; recurrence=annual'),
('6th-ayia-napa-medieval-festival', 'famagusta', '6th Ayia Napa Medieval Festival', '6th Ayia Napa Medieval Festival', '6th Ayia Napa Medieval Festival', '6th Ayia Napa Medieval Festival', 'A medieval-themed festival with a street parade, dance and music performances, dramatic presentations and participating groups from all over Europe. Held around the Ayia Napa monastery and old town.', 'Ένα φεστιβάλ με μεσαιωνική θεματική, με παρέλαση στους δρόμους, χορευτικές και μουσικές παραστάσεις, θεατρικά δρώμενα και συμμετέχουσες ομάδες από όλη την Ευρώπη. Πραγματοποιείται γύρω από το μοναστήρι και την παλιά πόλη της Αγίας Νάπας.', 'Un festival cu temă medievală, cu paradă stradală, spectacole de dans și muzică, reprezentații dramatice și grupuri participante din toată Europa. Se desfășoară în jurul mănăstirii și al orașului vechi din Ayia Napa.', 'مهرجان بطابع القرون الوسطى يتضمّن استعراضًا في الشوارع وعروض رقص وموسيقى وعروضًا درامية ومجموعات مشاركة من مختلف أنحاء أوروبا. يُقام حول دير أيا نابا والبلدة القديمة.', 'Ayia Napa Old Town & Monastery', '2026-10-14 18:00:00+03'::timestamptz, '2026-10-18 23:00:00+03'::timestamptz, 'Free', 'https://www.loveayianapa.com/festivals-in-ayia-napa.html', null, 34.9885, 34, array['medieval','festival','cultural','famagusta']::text[], 'published', 'https://cyprus-mail.com/2026/03/08/ayia-napa-festivals-to-look-forward-to', 'Ayia Napa Municipality', null, 'town', 'annual', 'confirmed', 'date_confidence=confirmed; recurrence=annual'),
('cyprus-grape-festival-limassol-wine-villages', 'limassol', 'Cyprus Grape Festival (Limassol Wine Villages)', 'Cyprus Grape Festival (Limassol Wine Villages)', 'Cyprus Grape Festival (Limassol Wine Villages)', 'Cyprus Grape Festival (Limassol Wine Villages)', 'Across September and October the Limassol wine villages (Koilani, Arsos, Vouni, Lofou, Vasa, Kilani) hold grape and wine feasts with wine-making demonstrations, grape products, folk music and dancing. Free village celebrations reviving old harvest customs.', 'Τον Σεπτέμβριο και τον Οκτώβριο τα κρασοχώρια της Λεμεσού (Κοιλάνι, Άρσος, Βουνί, Λόφου, Βάσα, Κιλάνι) διοργανώνουν γιορτές σταφυλιού και κρασιού με επιδείξεις οινοποίησης, προϊόντα σταφυλιού, παραδοσιακή μουσική και χορό. Δωρεάν χωριάτικες γιορτές που αναβιώνουν παλιά έθιμα του τρύγου.', 'Pe parcursul lunilor septembrie și octombrie, satele viticole din Limassol (Koilani, Arsos, Vouni, Lofou, Vasa, Kilani) găzduiesc sărbători ale strugurilor și ale vinului, cu demonstrații de vinificație, produse din struguri, muzică populară și dansuri. Sărbători sătești gratuite care readuc la viață vechile obiceiuri ale recoltei.', 'على امتداد سبتمبر وأكتوبر، تقيم قرى النبيذ في ليماسول (كويلاني وأرسوس وفوني ولوفو وفاسا وكيلاني) احتفالات بالعنب والنبيذ تشمل عروض صناعة النبيذ ومنتجات العنب والموسيقى الشعبية والرقص. احتفالات قروية مجانية تُحيي عادات الحصاد القديمة.', 'Koilani and other Limassol wine villages', '2026-10-04 11:00:00+03'::timestamptz, null, 'Free', null, null, 34.8281, 32.8497, array['wine','grape','village','limassol']::text[], 'draft', 'https://www.cyprusalive.com/en/grape-festival0', 'Limassol wine-village community councils', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('paphos-banana-festival-kissonerga', 'paphos', 'Paphos Banana Festival (Kissonerga)', 'Paphos Banana Festival (Kissonerga)', 'Paphos Banana Festival (Kissonerga)', 'Paphos Banana Festival (Kissonerga)', 'Kissonerga village celebrates its famous banana plantations with plantation visits, walks to nearby archaeological sites, banana-based sweets and traditional food, music and dancing. Free entry; the exact October date is announced closer to the event.', 'Το χωριό Κισσόνεργα γιορτάζει τις ξακουστές φυτείες μπανάνας του με επισκέψεις σε φυτείες, περιπάτους σε κοντινούς αρχαιολογικούς χώρους, γλυκά με βάση την μπανάνα και παραδοσιακό φαγητό, μουσική και χορό. Είσοδος δωρεάν· η ακριβής ημερομηνία τον Οκτώβριο ανακοινώνεται πιο κοντά στην εκδήλωση.', 'Satul Kissonerga își sărbătorește renumitele plantații de banane cu vizite pe plantații, plimbări spre siturile arheologice din apropiere, dulciuri pe bază de banane și mâncare tradițională, muzică și dansuri. Intrare gratuită; data exactă din octombrie este anunțată mai aproape de eveniment.', 'تحتفل قرية كيسونيرغا بمزارع الموز الشهيرة فيها من خلال زيارات للمزارع وجولات مشي إلى المواقع الأثرية القريبة وحلويات بالموز وأطعمة تقليدية وموسيقى ورقص. الدخول مجاني؛ ويُعلَن موعد أكتوبر الدقيق مع اقتراب الفعالية.', 'Kissonerga Village Square', '2026-10-17 16:00:00+03'::timestamptz, '2026-10-17 22:00:00+03'::timestamptz, 'Free', null, null, 34.8017, 32.403, array['food','village','festival','paphos']::text[], 'draft', 'https://kato-paphos-apartment.com/blog/paphos-festivals/', 'Kissonerga Community Council', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('zeytinlik-olive-festival', 'kyrenia', 'Zeytinlik Olive Festival', 'Zeytinlik Olive Festival', 'Zeytinlik Olive Festival', 'Zeytinlik Olive Festival', 'An autumn harvest festival in the Kyrenia-region village of Zeytinlik celebrating Mediterranean olive culture with olive-oil tastings, traditional food stalls, folk performances and artisan craft markets. Family-friendly and easily reached from Kyrenia town.', 'Ένα φθινοπωρινό φεστιβάλ συγκομιδής στο χωριό Zeytinlik της περιοχής Κερύνειας, που γιορτάζει τη μεσογειακή κουλτούρα της ελιάς με γευσιγνωσίες ελαιολάδου, πάγκους με παραδοσιακό φαγητό, λαϊκές παραστάσεις και αγορές χειροτεχνίας. Φιλικό προς τις οικογένειες και εύκολα προσβάσιμο από την πόλη της Κερύνειας.', 'Un festival de toamnă al recoltei în satul Zeytinlik, din regiunea Kyrenia, care celebrează cultura mediteraneeană a măslinului, cu degustări de ulei de măsline, standuri cu mâncare tradițională, spectacole folclorice și târguri de meșteșuguri artizanale. Prietenos cu familiile și ușor accesibil din orașul Kyrenia.', 'مهرجان حصاد خريفي في قرية زيتينليك بمنطقة كيرينيا يحتفي بثقافة الزيتون المتوسطية بتذوّق زيت الزيتون وأكشاك الطعام التقليدي والعروض الشعبية وأسواق الحرف اليدوية. ملائم للعائلات ويسهل الوصول إليه من مدينة كيرينيا.', 'Zeytinlik Village, near Kyrenia', '2026-10-10 10:00:00+03'::timestamptz, '2026-10-11 22:00:00+03'::timestamptz, 'Free', null, null, 35.323, 33.307, array['olive','food','harvest','kyrenia']::text[], 'draft', 'https://www.whatsonintrnc.com/festivals/zeytinlik-olive-festival', 'Zeytinlik village community', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('kypria-international-festival', 'nicosia', 'Kypria International Festival', 'Kypria International Festival', 'Kypria International Festival', 'Kypria International Festival', 'Cyprus''s flagship state cultural festival, running since 1990, presenting world-class music, dance, opera, ballet and performance art at venues across the island each autumn. The programme and exact dates are announced annually by the Deputy Ministry of Culture.', 'Το κορυφαίο κρατικό πολιτιστικό φεστιβάλ της Κύπρου, που διοργανώνεται από το 1990 και παρουσιάζει μουσική, χορό, όπερα, μπαλέτο και performance art παγκόσμιας κλάσης σε χώρους σε όλο το νησί κάθε φθινόπωρο. Το πρόγραμμα και οι ακριβείς ημερομηνίες ανακοινώνονται κάθε χρόνο από το Υφυπουργείο Πολιτισμού.', 'Festivalul cultural de stat emblematic al Ciprului, organizat din 1990, care prezintă muzică, dans, operă, balet și artă performativă de talie mondială, în spații de pe întreaga insulă, în fiecare toamnă. Programul și datele exacte sunt anunțate anual de Ministerul Adjunct al Culturii.', 'المهرجان الثقافي الرسمي الأبرز في قبرص، ويُقام منذ عام 1990، ويقدّم موسيقى ورقصًا وأوبرا وباليه وفنون أداء بمستوى عالمي في أماكن مختلفة عبر الجزيرة كل خريف. تُعلن الوزارة الفرعية للثقافة البرنامج والمواعيد الدقيقة سنويًا.', 'Various venues across Cyprus', '2026-10-01 20:00:00+03'::timestamptz, '2026-11-15 23:00:00+02'::timestamptz, null, null, null, 35.1856, 33.3823, array['cultural','music','opera','nicosia']::text[], 'draft', 'https://en.wikipedia.org/wiki/Kypria_festival', 'Deputy Ministry of Culture, Cyprus', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('radisson-blu-larnaka-international-marathon', 'larnaca', 'Radisson Blu Larnaka International Marathon', 'Radisson Blu Larnaka International Marathon', 'Radisson Blu Larnaka International Marathon', 'Radisson Blu Larnaka International Marathon', 'A major annual road-running event with marathon, half-marathon and shorter family races along a flat coastal route starting from the Finikoudes promenade. One of Cyprus''s largest sporting happenings, typically held in mid-November.', 'Μια μεγάλη ετήσια διοργάνωση αγώνων δρόμου, με μαραθώνιο, ημιμαραθώνιο και μικρότερους οικογενειακούς αγώνες σε μια επίπεδη παραλιακή διαδρομή με αφετηρία τον πεζόδρομο των Φοινικούδων. Ένα από τα μεγαλύτερα αθλητικά γεγονότα της Κύπρου, που συνήθως πραγματοποιείται στα μέσα Νοεμβρίου.', 'Un important eveniment anual de alergare pe șosea, cu maraton, semimaraton și curse mai scurte pentru familii, pe un traseu de coastă plat care pornește de pe promenada Finikoudes. Unul dintre cele mai mari evenimente sportive din Cipru, organizat de regulă la mijlocul lunii noiembrie.', 'فعالية جري سنوية كبرى على الطرق تشمل ماراثونًا ونصف ماراثون وسباقات عائلية أقصر على مسار ساحلي مستوٍ ينطلق من كورنيش فينيكوديس. من أكبر الأحداث الرياضية في قبرص، ويُقام عادةً في منتصف نوفمبر.', 'Finikoudes Promenade, Larnaca', '2026-11-15 07:30:00+02'::timestamptz, '2026-11-15 14:00:00+02'::timestamptz, 'Registration fee (runners)', null, null, 34.9182, 33.635, array['sport','marathon','annual','larnaca']::text[], 'draft', 'https://larnakaregion.com/news/autumns-events', 'Larnaka Municipality / event organisers', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('paphos-christmas-lights-and-tree-lighting', 'paphos', 'Paphos Christmas Lights & Tree Lighting', 'Paphos Christmas Lights & Tree Lighting', 'Paphos Christmas Lights & Tree Lighting', 'Paphos Christmas Lights & Tree Lighting', 'Paphos kicks off the festive season with the Christmas tree and city-lights switch-on at Kennedy Square, accompanied by a parade, musical performances and festive stalls. Free public celebration in late November.', 'Η Πάφος ανοίγει την εορταστική περίοδο με τη φωταγώγηση του χριστουγεννιάτικου δέντρου και των φώτων της πόλης στην Πλατεία Κένεντι, συνοδεία παρέλασης, μουσικών παραστάσεων και εορταστικών πάγκων. Δωρεάν δημόσια γιορτή στα τέλη Νοεμβρίου.', 'Paphos deschide sezonul sărbătorilor cu aprinderea bradului de Crăciun și a luminilor orașului în Piața Kennedy, însoțită de o paradă, spectacole muzicale și standuri festive. Sărbătoare publică gratuită, la sfârșitul lunii noiembrie.', 'تفتتح بافوس موسم الأعياد بإضاءة شجرة الميلاد وأنوار المدينة في ساحة كينيدي، يرافقها استعراض وعروض موسيقية وأكشاك احتفالية. احتفال عام مجاني في أواخر نوفمبر.', 'Kennedy Square, Paphos', '2026-11-27 18:00:00+02'::timestamptz, null, 'Free', null, null, 34.772, 32.429, array['christmas','festive','family','paphos']::text[], 'draft', 'https://home.cy/article/december-in-cyprus-a-festive-guide-to-christmas-villages-markets-seasonal-events', 'Paphos Municipality', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('ayia-napa-marina-christmas-village', 'famagusta', 'Ayia Napa Marina Christmas Village', 'Ayia Napa Marina Christmas Village', 'Ayia Napa Marina Christmas Village', 'Ayia Napa Marina Christmas Village', 'A festive village at the luxury Ayia Napa Marina with themed zones offering food, creative workshops, entertainment and holiday activities from late November through December. A seasonal highlight on the Famagusta coast.', 'Ένα εορταστικό χωριό στην πολυτελή μαρίνα της Αγίας Νάπας, με θεματικές ζώνες που προσφέρουν φαγητό, δημιουργικά εργαστήρια, ψυχαγωγία και εορταστικές δραστηριότητες από τα τέλη Νοεμβρίου έως τον Δεκέμβριο. Ένα από τα σημαντικότερα γεγονότα της περιόδου στην ακτή της Αμμοχώστου.', 'Un sat festiv în cadrul luxoasei Ayia Napa Marina, cu zone tematice care oferă mâncare, ateliere creative, divertisment și activități de sărbători, de la sfârșitul lunii noiembrie și pe tot parcursul lunii decembrie. Un punct de atracție sezonier pe coasta Famagusta.', 'قرية احتفالية في Ayia Napa Marina الفاخرة بمناطق مواضيعية تقدّم الطعام وورش العمل الإبداعية والترفيه وأنشطة الأعياد من أواخر نوفمبر حتى نهاية ديسمبر. من أبرز فعاليات الموسم على ساحل فاماغوستا.', 'Ayia Napa Marina', '2026-11-28 16:00:00+02'::timestamptz, '2026-12-28 22:00:00+02'::timestamptz, 'Free entry (some activities ticketed)', null, null, 34.9793, 33.982, array['christmas','market','family','famagusta']::text[], 'draft', 'https://home.cy/article/december-in-cyprus-a-festive-guide-to-christmas-villages-markets-seasonal-events', 'Ayia Napa Marina', null, 'exact', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('lefkara-christmas-village', 'larnaca', 'Lefkara Christmas Village', 'Lefkara Christmas Village', 'Lefkara Christmas Village', 'Lefkara Christmas Village', 'The lace-and-silverware village of Pano Lefkara becomes an official Christmas Village with festive stalls, entertainment and seasonal activities from late November into early January. Open on weekends and holidays through the season.', 'Το χωριό της δαντέλας και της αργυροχοΐας, τα Πάνω Λεύκαρα, μετατρέπεται σε επίσημο Χριστουγεννιάτικο Χωριό με εορταστικούς πάγκους, ψυχαγωγία και δραστηριότητες της περιόδου, από τα τέλη Νοεμβρίου έως τις αρχές Ιανουαρίου. Ανοιχτό τα σαββατοκύριακα και τις αργίες καθ'' όλη τη διάρκεια της περιόδου.', 'Satul dantelei și al argintăriei Pano Lefkara devine un Sat de Crăciun oficial, cu standuri festive, divertisment și activități sezoniere, de la sfârșitul lunii noiembrie până la începutul lunii ianuarie. Deschis în weekenduri și de sărbători pe tot parcursul sezonului.', 'تتحوّل قرية بانو ليفكارا الشهيرة بالدانتيل والفضّيات إلى قرية ميلادية رسمية بأكشاك احتفالية وترفيه وأنشطة موسمية من أواخر نوفمبر حتى أوائل يناير. تفتح أبوابها في عطلات نهاية الأسبوع والأعياد طوال الموسم.', 'Pano Lefkara', '2026-11-21 16:00:00+02'::timestamptz, '2027-01-06 22:00:00+02'::timestamptz, 'Free', null, null, 34.8656, 33.3049, array['christmas','village','crafts','larnaca']::text[], 'draft', 'https://larnakaregion.com/news/autumns-events', 'Deputy Ministry of Tourism / Lefkara', null, 'exact', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('the-jolly-road-christmas-market-nicosia', 'nicosia', 'The Jolly Road Christmas Market (Nicosia)', 'The Jolly Road Christmas Market (Nicosia)', 'The Jolly Road Christmas Market (Nicosia)', 'The Jolly Road Christmas Market (Nicosia)', 'Makariou Avenue in central Nicosia transforms into a festive market of wooden huts selling handcrafted gifts, festive food, sweets and drinks. Free admission, running from early December into early January.', 'Η Λεωφόρος Μακαρίου στο κέντρο της Λευκωσίας μεταμορφώνεται σε μια εορταστική αγορά με ξύλινα σπιτάκια που πωλούν χειροποίητα δώρα, εορταστικό φαγητό, γλυκά και ποτά. Είσοδος ελεύθερη, από τις αρχές Δεκεμβρίου έως τις αρχές Ιανουαρίου.', 'Bulevardul Makariou din centrul orașului Nicosia se transformă într-un târg festiv cu căsuțe din lemn care vând cadouri lucrate manual, mâncare de sărbători, dulciuri și băuturi. Intrare gratuită, deschis de la începutul lunii decembrie până la începutul lunii ianuarie.', 'يتحوّل شارع ماكاريو في وسط نيقوسيا إلى سوق احتفالي من الأكواخ الخشبية تبيع الهدايا المصنوعة يدويًا والأطعمة الاحتفالية والحلويات والمشروبات. الدخول مجاني، ويستمرّ من أوائل ديسمبر حتى أوائل يناير.', 'Makariou Avenue, Nicosia', '2026-12-01 17:00:00+02'::timestamptz, '2027-01-08 22:00:00+02'::timestamptz, 'Free', 'https://eventor.com.cy/events/nicosia/the-jolly-road-christmas-market-in-nicosia-10743', null, 35.162, 33.362, array['christmas','market','shopping','nicosia']::text[], 'draft', 'https://eventor.com.cy/events/nicosia/the-jolly-road-christmas-market-in-nicosia-10743', 'Three Star Events', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('larnaca-christmas-market-st-lazarus-square', 'larnaca', 'Larnaca Christmas Market (St Lazarus Square)', 'Larnaca Christmas Market (St Lazarus Square)', 'Larnaca Christmas Market (St Lazarus Square)', 'Larnaca Christmas Market (St Lazarus Square)', 'Over 200 stalls fill the square around the church of St Lazarus with souvenirs, gifts and street food during the city''s festive market in early December. A small entry fee applies.', 'Πάνω από 200 πάγκοι γεμίζουν την πλατεία γύρω από την εκκλησία του Αγίου Λαζάρου με σουβενίρ, δώρα και street food, στην εορταστική αγορά της πόλης στις αρχές Δεκεμβρίου. Ισχύει μικρό αντίτιμο εισόδου.', 'Peste 200 de standuri umplu piața din jurul bisericii Sfântul Lazăr cu suveniruri, cadouri și street food, în cadrul târgului festiv al orașului, la începutul lunii decembrie. Se percepe o mică taxă de intrare.', 'يملأ أكثر من 200 كشك الساحة المحيطة بكنيسة القديس لعازر بالتذكارات والهدايا وأطعمة الشوارع خلال سوق المدينة الاحتفالي في أوائل ديسمبر. تُطبَّق رسوم دخول رمزية.', 'St Lazarus Square, Larnaca', '2026-12-04 16:00:00+02'::timestamptz, '2026-12-06 22:00:00+02'::timestamptz, '€2.50', null, null, 34.9107, 33.6352, array['christmas','market','food','larnaca']::text[], 'draft', 'https://home.cy/article/december-in-cyprus-a-festive-guide-to-christmas-villages-markets-seasonal-events', 'Larnaka Municipality', null, 'exact', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('limassol-christmas-festive-market', 'limassol', 'Limassol Christmas Festive Market', 'Limassol Christmas Festive Market', 'Limassol Christmas Festive Market', 'Limassol Christmas Festive Market', 'Limassol''s festive season brings a Christmas show of decorations, gifts and handcrafted items plus market stalls, mulled wine and a kids'' train along Anexartisias Street. Free family festivities across December.', 'Η εορταστική περίοδος της Λεμεσού φέρνει ένα χριστουγεννιάτικο πανόραμα από στολίδια, δώρα και χειροποίητα είδη, καθώς και πάγκους αγοράς, ζεστό κρασί (mulled wine) και ένα παιδικό τρενάκι κατά μήκος της οδού Ανεξαρτησίας. Δωρεάν οικογενειακές γιορτές σε όλο τον Δεκέμβριο.', 'Sezonul sărbătorilor din Limassol aduce un spectacol de Crăciun cu decorațiuni, cadouri și obiecte lucrate manual, plus standuri, vin fiert și un trenuleț pentru copii de-a lungul străzii Anexartisias. Festivități gratuite pentru familii pe tot parcursul lunii decembrie.', 'يجلب موسم الأعياد في ليماسول عرضًا ميلاديًا من الزينة والهدايا والمصنوعات اليدوية إضافة إلى أكشاك السوق والنبيذ الساخن بالتوابل وقطار للأطفال على طول شارع أنيكسارتيسياس. احتفالات عائلية مجانية طوال ديسمبر.', 'Anexartisias Street & central Limassol', '2026-12-12 10:00:00+02'::timestamptz, '2026-12-21 21:00:00+02'::timestamptz, 'Free', null, null, 34.6841, 33.0413, array['christmas','market','family','limassol']::text[], 'draft', 'https://home.cy/article/december-in-cyprus-a-festive-guide-to-christmas-villages-markets-seasonal-events', 'Municipality of Limassol', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('limassol-carnival', 'limassol', 'Limassol Carnival', 'Limassol Carnival', 'Limassol Carnival', 'Limassol Carnival', 'Cyprus''s biggest carnival fills Limassol with two weeks of masked balls, children''s events and street parties, climaxing in the Grand Carnival Parade along Archbishop Makarios III Avenue. Free public celebration tied to the Orthodox pre-Lent calendar.', 'Το μεγαλύτερο καρναβάλι της Κύπρου γεμίζει τη Λεμεσό με δύο εβδομάδες μασκέ χορών, παιδικών εκδηλώσεων και πάρτι στους δρόμους, με αποκορύφωμα τη Μεγάλη Καρναβαλίστικη Παρέλαση κατά μήκος της Λεωφόρου Αρχιεπισκόπου Μακαρίου Γ΄. Δωρεάν δημόσια γιορτή συνδεδεμένη με το ορθόδοξο εορτολόγιο της Αποκριάς.', 'Cel mai mare carnaval din Cipru umple orașul Limassol cu două săptămâni de baluri mascate, evenimente pentru copii și petreceri stradale, care culminează cu Marea Paradă a Carnavalului pe bulevardul Arhiepiscop Makarios III. Sărbătoare publică gratuită, legată de calendarul ortodox dinaintea Postului Mare.', 'أكبر كرنفال في قبرص يملأ ليماسول بأسبوعين من الحفلات الراقصة المقنّعة وفعاليات الأطفال وحفلات الشوارع، ويبلغ ذروته باستعراض الكرنفال الكبير على شارع المطران مكاريوس الثالث. احتفال عام مجاني مرتبط بتقويم ما قبل الصوم الأرثوذكسي.', 'Archbishop Makarios III Avenue & central Limassol', '2027-03-05 10:00:00+02'::timestamptz, '2027-03-15 22:00:00+02'::timestamptz, 'Free', 'https://www.limassol.org.cy/', null, 34.6841, 33.0413, array['carnival','parade','festival','limassol']::text[], 'draft', 'https://www.visitcyprus.com/event/limassol-carnival-12-22-2-2026/', 'Municipality of Limassol', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('bellapais-international-music-festival', 'kyrenia', 'Bellapais International Music Festival', 'Bellapais International Music Festival', 'Bellapais International Music Festival', 'Bellapais International Music Festival', 'A prestigious classical music festival held over several weeks in late spring in the atmospheric 13th-century Bellapais Abbey near Kyrenia, featuring international orchestras, chamber ensembles and soloists. Founded in the late 1990s.', 'Ένα φημισμένο φεστιβάλ κλασικής μουσικής που πραγματοποιείται επί αρκετές εβδομάδες στα τέλη της άνοιξης, στο ατμοσφαιρικό Αβαείο του Μπελλαπάις (Bellapais) του 13ου αιώνα, κοντά στην Κερύνεια, με διεθνείς ορχήστρες, σύνολα μουσικής δωματίου και σολίστ. Ιδρύθηκε στα τέλη της δεκαετίας του 1990.', 'Un prestigios festival de muzică clasică desfășurat pe parcursul mai multor săptămâni la sfârșitul primăverii, în atmosfera Abației Bellapais din secolul al XIII-lea, în apropiere de Kyrenia, cu orchestre internaționale, ansambluri de cameră și soliști. Fondat la sfârșitul anilor 1990.', 'مهرجان راقٍ للموسيقى الكلاسيكية يُقام على مدى أسابيع في أواخر الربيع في دير بيلابايس الساحر الذي يعود إلى القرن الثالث عشر قرب كيرينيا، ويضمّ أوركسترات عالمية وفرقًا للموسيقى الحجرية وعازفين منفردين. تأسّس في أواخر التسعينيات.', 'Bellapais Abbey, near Kyrenia', '2027-05-15 20:30:00+03'::timestamptz, '2027-06-15 23:00:00+03'::timestamptz, null, null, null, 35.3059, 33.3557, array['classical','music','concert','kyrenia']::text[], 'draft', 'https://www.whatsonintrnc.com/festivals/bellapais-music-festival', 'North Cyprus International Bellapais Music Festival', null, 'exact', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('kataklysmos-festival-of-the-flood-larnaca', 'larnaca', 'Kataklysmos (Festival of the Flood), Larnaca', 'Kataklysmos (Festival of the Flood), Larnaca', 'Kataklysmos (Festival of the Flood), Larnaca', 'Kataklysmos (Festival of the Flood), Larnaca', 'Larnaca''s largest and oldest celebration, a UNESCO-recognised Pentecost festival spanning the Finikoudes seafront with stalls, craft demonstrations, a beach funfair, folk and modern concerts and water games. Free; tied to the Orthodox Pentecost calendar.', 'Η μεγαλύτερη και παλαιότερη γιορτή της Λάρνακας· μια αναγνωρισμένη από την UNESCO γιορτή της Πεντηκοστής που απλώνεται στην παραλιακή των Φοινικούδων, με πάγκους, επιδείξεις χειροτεχνίας, λούνα παρκ στην παραλία, λαϊκές και σύγχρονες συναυλίες και παιχνίδια με νερό. Δωρεάν· συνδέεται με το ορθόδοξο εορτολόγιο της Πεντηκοστής.', 'Cea mai mare și mai veche sărbătoare din Larnaca, un festival de Rusalii recunoscut de UNESCO, care se întinde de-a lungul falezei Finikoudes, cu standuri, demonstrații de meșteșuguri, un bâlci pe plajă, concerte folclorice și moderne și jocuri pe apă. Gratuit; legat de calendarul ortodox al Rusaliilor.', 'أكبر وأقدم احتفال في لارنكا، وهو مهرجان العنصرة المُدرَج لدى اليونسكو ويمتدّ على واجهة فينيكوديس البحرية بأكشاك وعروض حرفية ومدينة ملاهٍ شاطئية وحفلات شعبية وحديثة وألعاب مائية. مجاني؛ ومرتبط بتقويم العنصرة الأرثوذكسي.', 'Finikoudes Promenade, Larnaca', '2027-06-18 10:00:00+03'::timestamptz, '2027-06-22 23:00:00+03'::timestamptz, 'Free', 'https://larnakaregion.com/', null, 34.9134, 33.6366, array['traditional','waterfront','festival','larnaca']::text[], 'draft', 'https://larnakaregion.com/event-detail/-kataklysmos-2026-festival-flood', 'Larnaka Tourism Board', null, 'exact', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('fengaros-festival', 'nicosia', 'Fengaros Festival', 'Fengaros Festival', 'Fengaros Festival', 'Fengaros Festival', 'A leading Eastern-Mediterranean independent music festival with dozens of Cypriot and international acts across multiple stages over three summer nights, held at Petrides Farm Park in Marki. Camping available; all ages.', 'Ένα κορυφαίο ανεξάρτητο μουσικό φεστιβάλ της Ανατολικής Μεσογείου, με δεκάδες Κύπριους και διεθνείς καλλιτέχνες σε πολλαπλές σκηνές, επί τρεις καλοκαιρινές νύχτες, στο Petrides Farm Park στο Μαρκί. Διαθέσιμο camping· για όλες τις ηλικίες.', 'Un festival de muzică independentă de top din estul Mediteranei, cu zeci de artiști ciprioți și internaționali pe mai multe scene, timp de trei nopți de vară, organizat la Petrides Farm Park din Marki. Camping disponibil; pentru toate vârstele.', 'مهرجان رائد للموسيقى المستقلة في شرق المتوسط يضمّ عشرات الفرق القبرصية والعالمية على منصّات متعددة على مدى ثلاث ليالٍ صيفية، يُقام في Petrides Farm Park في ماركي. التخييم متاح؛ ولجميع الأعمار.', 'Petrides Farm Park, Marki', '2027-07-30 18:00:00+03'::timestamptz, '2027-08-01 23:00:00+03'::timestamptz, 'Ticketed', 'https://www.fengaros.com/', null, 35.017, 33.421, array['music','festival','indie','nicosia']::text[], 'draft', 'https://www.musicfestivalwizard.com/festivals/fengaros-festival-2026/', 'Louvana Records / Fengaros', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('anthestiria-flower-festival-limassol', 'limassol', 'Anthestiria Flower Festival (Limassol)', 'Anthestiria Flower Festival (Limassol)', 'Anthestiria Flower Festival (Limassol)', 'Anthestiria Flower Festival (Limassol)', 'A May flower festival reviving the ancient Athenian celebration of Dionysus, centred on a parade of beautifully decorated flower floats along the Limassol seafront. Free public event organised by the municipality.', 'Μια γιορτή λουλουδιών τον Μάιο που αναβιώνει την αρχαία αθηναϊκή γιορτή του Διονύσου, με επίκεντρο μια παρέλαση από πανέμορφα στολισμένα ανθοστόλιστα άρματα κατά μήκος της παραλιακής της Λεμεσού. Δωρεάν δημόσια εκδήλωση που διοργανώνεται από τον δήμο.', 'Un festival al florilor din luna mai, care readuce la viață străvechea sărbătoare ateniană a lui Dionysos, având în centru o paradă de care alegorice frumos decorate cu flori, de-a lungul falezei din Limassol. Eveniment public gratuit organizat de municipalitate.', 'مهرجان زهور في مايو يُحيي احتفال أثينا القديم بديونيسوس، ويتمحور حول استعراض لعربات زهور مزيّنة ببراعة على طول واجهة ليماسول البحرية. فعالية عامة مجانية تنظّمها البلدية.', 'Limassol Seafront (Molos)', '2027-05-14 10:00:00+03'::timestamptz, '2027-05-17 21:00:00+03'::timestamptz, 'Free', 'https://www.limassol.org.cy/en/Anthestiria', null, 34.672, 33.047, array['flowers','parade','spring','limassol']::text[], 'draft', 'https://www.limassol.org.cy/en/Anthestiria', 'Municipality of Limassol', null, 'town', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual'),
('25th-pafos-aphrodite-festival-opera-at-paphos-castle', 'paphos', '25th Pafos Aphrodite Festival (Opera at Paphos Castle)', '25th Pafos Aphrodite Festival (Opera at Paphos Castle)', '25th Pafos Aphrodite Festival (Opera at Paphos Castle)', '25th Pafos Aphrodite Festival (Opera at Paphos Castle)', 'The flagship open-air opera festival staged each September in the floodlit square of the medieval Paphos Castle at Kato Paphos harbour, with a full opera performed by an international company and the Cyprus Symphony Orchestra. The 2026 edition presented Donizetti''s ''L''Elisir d''Amore''; the 2027 edition date is estimated.', 'Το κορυφαίο υπαίθριο φεστιβάλ όπερας που ανεβαίνει κάθε Σεπτέμβριο στη φωταγωγημένη πλατεία του μεσαιωνικού Κάστρου της Πάφου, στο λιμάνι της Κάτω Πάφου, με μια ολοκληρωμένη όπερα από διεθνή θίασο και τη Συμφωνική Ορχήστρα Κύπρου. Η διοργάνωση του 2026 παρουσίασε τον «Ελιξίριο του Έρωτα» («L''Elisir d''Amore») του Ντονιτσέτι· η ημερομηνία της διοργάνωσης του 2027 είναι εκτιμώμενη.', 'Festivalul emblematic de operă în aer liber, organizat în fiecare septembrie în piața luminată a Castelului medieval din Paphos, în portul Kato Paphos, cu o operă integrală interpretată de o companie internațională și de Orchestra Simfonică a Ciprului. Ediția din 2026 a prezentat opera „L''Elisir d''Amore” de Donizetti; data ediției din 2027 este estimativă.', 'مهرجان الأوبرا الأبرز في الهواء الطلق، يُقام كل سبتمبر في ساحة قلعة بافوس التي تعود للعصور الوسطى والمضاءة بالكشّافات على ميناء كاتو بافوس، بأوبرا كاملة تؤدّيها فرقة عالمية وأوركسترا قبرص السيمفونية. قدّمت نسخة 2026 أوبرا «L''Elisir d''Amore» لدونيزيتي؛ وموعد نسخة 2027 تقديري.', 'Square of the Medieval Castle of Pafos, Kato Paphos Harbour', '2027-09-03 20:00:00+03'::timestamptz, '2027-09-04 23:30:00+03'::timestamptz, '€35–€150', 'https://pafos.org.cy/24o-pafos-aphrodite-festival-2026/', null, 34.7534, 32.4076, array['opera','classical','festival','paphos']::text[], 'draft', 'https://www.visitcyprus.com/event/24th-pafos-aphrodite-festival-lelisir-damore-by-gaetano-donizetti-4-5-9-2026/', 'Pafos Aphrodite Festival', null, 'exact', 'annual', 'approximate', 'date_confidence=approximate; recurrence=annual')
